[CRITICAL] In /app/frontend/app/(tabs)/strategies.tsx add a togglePublish handler inside the Strategies component, e.g.:
   const togglePublish = async () => {
     if (!selected || !u) return;
     const isPub = !!(selected as any).is_public;
     try {
       if (isPub) await api.unpublishStrategy(u, selected.id);
       else await api.publishStrategy(u, selected.id);
       // refresh both the customs list AND the locally-selected modal state
       const list = await api.customStrategies(u);
       setStrategies((prev) => prev.map((s) => s.id === selected.id ? { ...s, is_public: !isPub } : s));
       setSelected((prev) => prev ? ({ ...prev, is_public: !isPub } as any) : prev);
     } catch (e: any) { Alert.alert('Publish failed', String(e?.message || e)); }
   };
